def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    for c in range(w):
        # Only columns with a nonzero vertical ray reaching the bottom are guides.
        if grid[h - 1][c] == 0:
            continue
        start = h - 1
        while start > 0 and grid[start - 1][c] != 0:
            start -= 1
        bars = []
        for r in range(h):
            if grid[r][c] != 0:
                continue
            left, right = c - 1, c + 1
            while left >= 0 and grid[r][left] == 0:
                left -= 1
            while right < w and grid[r][right] == 0:
                right += 1
            if left >= 0 and right < w and grid[r][left] == grid[r][right] != 0:
                bars.append((r, grid[r][left]))
        previous = -1
        for r, color in bars:
            for y in range(previous + 1, r + 1):
                out[y][c] = color
            previous = r
    return out
